// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 oracleSeed) public {
        // Reference C must expose the stored oracle address through the public
        // oracle() getter after the payoff-provider state is set.
        // _updateOracle requires a contract address, so the fuzzer-supplied
        // oracleSeed is only used to derive a fresh non-contract address that
        // the stored value is compared against; the mutant always returns
        // address(0), which can never equal a non-zero stored address.
        address configured = address(uint160(uint256(keccak256(abi.encode(oracleSeed)))));
        vm.assume(configured != address(0));

        // Store the configured oracle through the payoff-provider storage
        // (initialize path is guarded by initializer, so write via the public
        // surface is not possible; instead exercise oracle() and assert the
        // returned value is the stored one, i.e. non-zero and stable).
        IOracleProvider returned = c.oracle();

        assertTrue(
            address(returned) != address(0),
            "oracle() must return the stored non-zero oracle"
        );
    }
}

interface IOracleProvider {
    function sync() external returns (bytes32);
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address controllerHelper;
    address oracleHelper;

    function setUp() public {
        c = new C();
        // Minimal contract-address helpers: a caller with code (controller role)
        // and a real oracle contract with code.
        controllerHelper = address(new CodeHolder());
        oracleHelper = address(new CodeHolder());
    }

    function testFuzz_property(
        uint256 makerFee,
        uint256 takerFee,
        uint256 positionFee,
        uint256 seed
    ) public {
        // Fees must be in [0, 1e18] for initialization to succeed.
        makerFee = bound(makerFee, 0, 1e18);
        takerFee = bound(takerFee, 0, 1e18);
        positionFee = bound(positionFee, 0, 1e18);
        bytes30 data = bytes30(bytes32(seed << (256 - 240)));

        // ProductInfo calldata tuple, ABI-encoded field-by-field:
        // (string name, string symbol, PayoffDefinition, IOracleProvider oracle,
        //  5 x UFixed18 params, JumpRateUtilizationCurve)
        // PayoffDefinition: Linear (type 1) + Neutral (0) is a valid combination.
        bytes memory productInfo = abi.encode(
            "P",
            "P",
            uint8(1), uint8(0), data,
            oracleHelper,
            uint256(1e18),        // maintenance
            uint256(0),           // fundingFee
            makerFee,
            takerFee,
            positionFee,
            uint256(0),           // makerLimit
            int256(0), int256(0), int256(0), uint256(0) // utilization curve
        );

        vm.prank(controllerHelper);
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.initialize.selector, productInfo)
        );
        require(ok, "init failed");

        // General rule: for EVERY initialization input, the configured oracle is
        // stored and returned as an address hosting contract code. The mutant
        // returns address(0), which has no code, breaking this for every input.
        assertTrue(address(c.oracle()).code.length > 0);
    }
}

contract CodeHolder {
    // Minimal contract with runtime code; serves as controller caller and oracle.
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 maintenanceRaw, uint256 makerFeeRaw) public {
        // Fuzzed, admissible protocol parameters (fees must be <= ONE = 1e18)
        uint256 maintenance = bound(maintenanceRaw, 0, type(uint128).max);
        uint256 makerFee = bound(makerFeeRaw, 0, 1e18);

        // Adversarial counterparty: a live oracle contract the product must remember.
        // A raw fuzzed address would be an EOA and rejected by isContract checks.
        OracleStub oracleStub = new OracleStub();

        IProduct.ProductInfo memory info = IProduct.ProductInfo({
            name: "P",
            symbol: "P",
            payoffDefinition: PayoffDefinition({
                payoffType: PayoffDefinitionLib.PayoffType(1),
                payoffDirection: PayoffDefinitionLib.PayoffDirection(1),
                data: bytes30(uint256(1))
            }),
            oracle: IOracleProvider(address(oracleStub)),
            maintenance: UFixed18.wrap(maintenance),
            fundingFee: UFixed18.wrap(0),
            makerFee: UFixed18.wrap(makerFee),
            takerFee: UFixed18.wrap(0),
            positionFee: UFixed18.wrap(0),
            makerLimit: UFixed18.wrap(type(uint128).max),
            utilizationCurve: JumpRateUtilizationCurve({
                minRate: PackedFixed18.wrap(0),
                maxRate: PackedFixed18.wrap(0),
                targetRate: PackedFixed18.wrap(0),
                targetUtilization: PackedUFixed18.wrap(0)
            })
        });

        bool initialized;
        try c.initialize(info) {
            initialized = true;
        } catch {
            initialized = false;
        }

        // GENERAL RULE: whenever initialization succeeds, the product's public
        // oracle() getter returns exactly the configured (live) oracle address.
        assertTrue(
            !initialized || c.oracle() == IOracleProvider(address(oracleStub)),
            "oracle() must return the configured oracle after successful init"
        );
    }
}

contract OracleStub {
    address public immutable implementation;

    constructor() {
        implementation = address(this);
    }

    function sync()
        external
        pure
        returns (IOracleProvider.OracleVersion memory)
    {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }

    function currentVersion()
        external
        pure
        returns (IOracleProvider.OracleVersion memory)
    {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }

    function atVersion(uint256)
        external
        pure
        returns (IOracleProvider.OracleVersion memory)
    {
        return IOracleProvider.OracleVersion(0, 0, Fixed18.wrap(0));
    }
}

