pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    struct PD { uint8 payoffType; uint8 payoffDirection; bytes30 data; }
    struct Curve { int128 minRate; int128 maxRate; int128 targetRate; uint128 targetUtilization; }
    struct Info {
        string name;
        string symbol;
        PD payoffDefinition;
        address oracle;
        uint256 maintenance;
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        Curve utilizationCurve;
    }

    function setUp() public { c = new C(); }

    function testFuzz_property(uint8 payoffType, uint8 payoffDirection, uint64 seed) public {
        OracleStub stub = new OracleStub();

        Info memory info = Info({
            name: "P",
            symbol: "P",
            payoffDefinition: PD({payoffType: payoffType, payoffDirection: payoffDirection, data: bytes30(uint240(seed))}),
            oracle: address(stub),
            maintenance: uint256(1) * 1e18,
            fundingFee: 0,
            makerFee: 0,
            takerFee: 0,
            positionFee: 0,
            makerLimit: uint256(1000) * 1e18,
            utilizationCurve: Curve({minRate: 0, maxRate: 0, targetRate: 0, targetUtilization: 0})
        });

        (bool initOk, ) = address(c).call(
            abi.encodeWithSignature(
                "initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))",
                info
            )
        );

        bool viewOk = false;
        if (initOk) {
            try c.currentVersion() {
                viewOk = true;
            } catch {
                viewOk = false;
            }
        }

        assertTrue(!initOk || viewOk);
    }
}

contract OracleStub {
    function currentVersion() external view returns (uint256, uint256, int256) {
        return (1, block.timestamp, 0);
    }
    function atVersion(uint256) external view returns (uint256, uint256, int256) {
        return (1, block.timestamp, 0);
    }
    function sync() external returns (uint256, uint256, int256) {
        return (1, block.timestamp, 0);
    }
}

