pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    // Local ABI-layout mirrors of the file-level structs (used only to build calldata/decode returns).
    struct LocalPayoffDefinition {
        uint8 payoffType;
        uint8 payoffDirection;
        bytes30 data;
    }
    struct LocalCurve {
        int128 minRate;
        int128 maxRate;
        int128 targetRate;
        uint128 targetUtilization;
    }
    struct LocalProductInfo {
        string name;
        string symbol;
        LocalPayoffDefinition payoffDefinition;
        address oracle;
        uint256 maintenance;
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit;
        LocalCurve utilizationCurve;
    }

    bytes4 constant INIT_SEL =
        bytes4(keccak256("initialize((string,string,(uint8,uint8,bytes30),address,uint256,uint256,uint256,uint256,uint256,uint256,(int128,int128,int128,uint128)))"));
    bytes4 constant PD_SEL = bytes4(keccak256("payoffDefinition()"));

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint8 pdType, uint8 pdDir, bytes30 pdData) public {
        // Admissible domain: a meaningful (non-zero) payoff type, direction within 0..1, arbitrary data.
        vm.assume(pdType != 0);
        pdDir = uint8(bound(pdDir, 0, 1));

        // The product's controller is the caller (this test contract, which has code).
        // The oracle address only needs to be a contract: this test contract qualifies.
        LocalProductInfo memory info = LocalProductInfo({
            name: "t",
            symbol: "t",
            payoffDefinition: LocalPayoffDefinition({payoffType: pdType, payoffDirection: pdDir, data: pdData}),
            oracle: address(this),
            maintenance: 1e18,
            fundingFee: 0,
            makerFee: 0,
            takerFee: 0,
            positionFee: 0,
            makerLimit: 1e18,
            utilizationCurve: LocalCurve({minRate: 0, maxRate: 0, targetRate: 0, targetUtilization: 0})
        });

        bool initOk;
        try c.initialize(info) {
            initOk = true;
        } catch {
            initOk = false;
        }

        // If the supplied definition is outside the contract's validity domain, input is inadmissible.
        if (!initOk) return;

        // GENERAL RULE: after a successful initialization, the getter payoffDefinition() returns
        // exactly the payoff definition that was supplied to initialize() for every admissible input.
        (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSelector(PD_SEL));
        assertTrue(ok);

        bytes32 expectedData = bytes32(uint256(uint256(pdData) << 16)); // bytes30 left-aligned in a word
        bytes memory expected = abi.encode(pdType, pdDir, expectedData);
        assertTrue(keccak256(ret) == keccak256(expected));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 rawType, uint256 rawDirection, bytes30 data) public {
        // keep enums inside their declared ranges (admissible domain, still wide)
        vm.assume(rawType <= uint256(type(PayoffDefinitionLib.PayoffType).max));
        vm.assume(rawDirection <= uint256(type(PayoffDefinitionLib.PayoffDirection).max));
        // a zeroed definition cannot distinguish stored-vs-zeroed returns
        vm.assume(data != bytes30(0));

        PayoffDefinition memory pd = PayoffDefinition(
            PayoffDefinitionLib.PayoffType(rawType),
            PayoffDefinitionLib.PayoffDirection(rawDirection),
            data
        );

        IProduct.ProductInfo memory info;
        info.name = "T";
        info.symbol = "T";
        info.payoffDefinition = pd;
        info.oracle = IOracleProvider(address(new DummyOracle()));
        info.maintenance = UFixed18.wrap(1e18);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(type(uint128).max);
        info.utilizationCurve = JumpRateUtilizationCurve({
            minRate: PackedFixed18.wrap(0),
            maxRate: PackedFixed18.wrap(0),
            targetRate: PackedFixed18.wrap(0),
            targetUtilization: PackedUFixed18.wrap(0)
        });

        // Rule: whenever initialization with a definition succeeds, the public getter
        // must return exactly the definition that was supplied.
        try c.initialize(info) {
            PayoffDefinition memory got = c.payoffDefinition();
            assertTrue(
                got.data == data
                    && got.payoffType == PayoffDefinitionLib.PayoffType(rawType)
                    && got.payoffDirection == PayoffDefinitionLib.PayoffDirection(rawDirection)
            );
        } catch {
            // inadmissible combination on the reference contract: nothing to check
        }
    }
}

contract DummyOracle {
    function sync() external returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 0, timestamp: 0, price: Fixed18.wrap(0)});
    }
    function currentVersion() external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 0, timestamp: 0, price: Fixed18.wrap(0)});
    }
    function atVersion(uint256) external view returns (IOracleProvider.OracleVersion memory) {
        return IOracleProvider.OracleVersion({version: 0, timestamp: 0, price: Fixed18.wrap(0)});
    }
}
